      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : DivisionRing K] (a b c : K), (a - b) / c = a / c - b / c"
    },
    {
      "name": "EuclideanDomain.sub_mul_div_right",
      "module_name": "Mathlib.Algebra.EuclideanDomain.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : EuclideanDomain R] (x y z : R), y ≠ 0 → y ∣ x → (x - z * y) / y = x / y - z"
    },
    {
      "name": "tsub_div",
      "module_name": "Mathlib.Algebra.Order.Field.Canonical",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Semifield α] [inst_1 : LinearOrder α] [CanonicallyOrderedAdd α] [IsStrictOrderedRing α]\n  [inst_4 : Sub α] [OrderedSub α] (a b c : α), (a - b) / c = a / c - b / c"
    },
    {
      "name": "ENNReal.sub_div",
      "module_name": "Mathlib.Data.ENNReal.Inv",
      "kind": "theorem",
      "type": "∀ {a b c : ENNReal}, (0 < b → b < a → c ≠ 0) → (a - b) / c = a / c - b / c"
    },
    {
      "name": "NNReal.sub_div",
      "module_name": "Mathlib.Data.NNReal.Basic",
      "kind": "theorem",
      "type": "∀ (a b c : NNReal), (a - b) / c = a / c - b / c"
    }
  ]
